windows.checkout:
@echo off
node "<mcctl>" task run survival-backup
exit /b %errorlevel%

start.sh.text:
#!/bin/sh
'<entry>' start 'survival' || { echo; echo 'Failed to start.'; exit 1; }
exec '<entry>' console 'survival'

#!/bin/sh
'<node>' '<mcctl>' start 'survival' || { echo; echo 'Failed to start.'; exit 1; }
exec '<node>' '<mcctl>' console 'survival'

start.bat.text:
@echo off
title survival - SpawnLoft
"<entry>" start survival
if errorlevel 1 (echo.& echo Failed to start. & pause & exit /b 1)
"<entry>" console survival

@echo off
title survival - SpawnLoft
node "<mcctl>" start survival
if errorlevel 1 (echo.& echo Failed to start. & pause & exit /b 1)
node "<mcctl>" console survival
